    @Inject(method = "begin", at = @At("HEAD"), cancellable = true)
    private static void onBegin(int drawMode, VertexFormat format, CallbackInfoReturnable<BufferBuilder> cir) {
        // Just pass through - the format handling is done elsewhere
    }

    @Inject(method = "vertex", at = @At("HEAD"), cancellable = true)
