{"content":"package net.glesbridge.shim;

import org.lwjgl.gles.GLES30;
import org.lwjgl.gles.GLES31;
import org.lwjgl.gles.GLES32;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Compatibility shim for mods that call raw OpenGL (GL11/GL30) instead of RenderSystem.
 * This is a MINIMAL shim - only covers the most common calls.
 * Mods using raw GL are explicitly NOT fully supported - this is best-effort.
 */
public class GLESCompatShim {
    private static final Logger LOGGER = LoggerFactory.getLogger("GLES Bridge/Compat");

    // State to track if shim is active
    private static boolean shimActive = false;

    public static void enableShim() {
        if (!shimActive) {
            shimActive = true;
            LOGGER.info("GLES Compatibility Shim enabled - raw GL calls will be redirected to GLES");
        }
    }

    public static void disableShim() {
        shimActive = false;
        LOGGER.info("GLES Compatibility Shim disabled");
    }

    public static boolean isShimActive() {
        return shimActive;
    }

    // ===== GL11 =====

    public static void glEnable(int cap) {
        if (!shimActive) return;
        int glesCap = mapCap(cap);
        if (glesCap >= 0) GLES30.glEnable(glesCap);
        else LOGGER.debug("GL11 glEnable: unknown cap 0x{:X}", cap);
    }

    public static void glDisable(int cap) {
        if (!shimActive) return;
        int glesCap = mapCap(cap);
        if (glesCap >= 0) GLES30.glDisable(glesCap);
        else LOGGER.debug("GL11 glDisable: unknown cap 0x{:X}", cap);
    }

    public static void glViewport(int x, int y, int width, int height) {
        if (!shimActive) return;
        GLES30.glViewport(x, y, width, height);
    }

    public static void glClearColor(float red, float green, float blue, float alpha) {
        if (!shimActive) return;
        GLES30.glClearColor(red, green, blue, alpha);
    }

    public static void glClear(int mask) {
        if (!shimActive) return;
        GLES30.glClear(mapClearMask(mask));
    }

    public static void glColorMask(boolean red, boolean green, boolean blue, boolean alpha) {
        if (!shimActive) return;
        GLES30.glColorMask(red, green, blue, alpha);
    }

    public static void glDepthMask(boolean flag) {
        if (!shimActive) return;
        GLES30.glDepthMask(flag);
    }

    public static void glDepthFunc(int func) {
        if (!shimActive) return;
        GLES30.glDepthFunc(mapDepthFunc(func));
    }

    public static void glBlendFunc(int sfactor, int dfactor) {
        if (!shimActive) return;
        GLES30.glBlendFunc(mapBlendFactor(sfactor), mapBlendFactor(dfactor));
    }

    public static void glBlendFuncSeparate(int srcRGB, int dstRGB, int srcAlpha, int dstAlpha) {
        if (!shimActive) return;
        GLES30.glBlendFuncSeparate(mapBlendFactor(srcRGB), mapBlendFactor(dstRGB),
                                   mapBlendFactor(srcAlpha), mapBlendFactor(dstAlpha));
    }

    public static void glCullFace(int mode) {
        if (!shimActive) return;
        GLES30.glCullFace(mapCullFace(mode));
    }

    public static void glFrontFace(int mode) {
        if (!shimActive) return;
        GLES30.glFrontFace(mode == 0x0900 ? GLES30.GL_CCW : GLES30.GL_CW);
    }

    public static void glPolygonOffset(float factor, float units) {
        if (!shimActive) return;
        GLES30.glPolygonOffset(factor, units);
    }

    public static void glScissor(int x, int y, int width, int height) {
        if (!shimActive) return;
        GLES30.glScissor(x, y, width, height);
    }

    public static void glLineWidth(float width) {
        if (!shimActive) return;
        GLES30.glLineWidth(width);
    }

    // ===== GL15 / Buffer objects =====

    public static void glGenBuffers(int n, int[] buffers, int offset) {
        if (!shimActive) return;
        GLES30.glGenBuffers(n, buffers, offset);
    }

    public static void glGenBuffers(int[] buffers) {
        if (!shimActive) return;
        GLES30.glGenBuffers(buffers);
    }

    public static void glBindBuffer(int target, int buffer) {
        if (!shimActive) return;
        GLES30.glBindBuffer(target, buffer);
    }

    public static void glBufferData(int target, long size, long data, int usage) {
        if (!shimActive) return;
        GLES30.glBufferData(target, size, data, usage);
    }

    public static void glBufferData(int target, java.nio.Buffer data, int usage) {
        if (!shimActive) return;
        GLES30.glBufferData(target, data, usage);
    }

    public static void glBufferSubData(int target, long offset, long size, long data) {
        if (!shimActive) return;
        GLES30.glBufferSubData(target, offset, size, data);
    }

    public static void glBufferSubData(int target, long offset, java.nio.Buffer data) {
        if (!shimActive) return;
        GLES30.glBufferSubData(target, offset, data);
    }

    public static void glDeleteBuffers(int n, int[] buffers, int offset) {
        if (!shimActive) return;
        GLES30.glDeleteBuffers(n, buffers, offset);
    }

    public static void glDeleteBuffers(int[] buffers) {
        if (!shimActive) return;
        GLES30.glDeleteBuffers(buffers);
    }

    // ===== GL20 / Shaders =====

    public static int glCreateShader(int type) {
        if (!shimActive) return 0;
        return GLES30.glCreateShader(mapShaderType(type));
    }

    public static void glShaderSource(int shader, String source) {
        if (!shimActive) return;
        GLES30.glShaderSource(shader, convertGLSLtoESSL(source));
    }

    public static void glCompileShader(int shader) {
        if (!shimActive) return;
        GLES30.glCompileShader(shader);
    }

    public static int glCreateProgram() {
        if (!shimActive) return 0;
        return GLES30.glCreateProgram();
    }

    public static void glAttachShader(int program, int shader) {
        if (!shimActive) return;
        GLES30.glAttachShader(program, shader);
    }

    public static void glLinkProgram(int program) {
        if (!shimActive) return;
        GLES30.glLinkProgram(program);
    }

    public static void glUseProgram(int program) {
        if (!shimActive) return;
        GLES30.glUseProgram(program);
    }

    public static void glDeleteProgram(int program) {
        if (!shimActive) return;
        GLES30.glDeleteProgram(program);
    }

    public static void glDeleteShader(int shader) {
        if (!shimActive) return;
        GLES30.glDeleteShader(shader);
    }

    public static int glGetUniformLocation(int program, String name) {
        if (!shimActive) return -1;
        return GLES30.glGetUniformLocation(program, name);
    }

    public static int glGetAttribLocation(int program, String name) {
        if (!shimActive) return -1;
        return GLES30.glGetAttribLocation(program, name);
    }

    public static void glUniform1i(int location, int v0) {
        if (!shimActive) return;
        GLES30.glUniform1i(location, v0);
    }

    public static void glUniform1f(int location, float v0) {
        if (!shimActive) return;
        GLES30.glUniform1f(location, v0);
    }

    public static void glUniform2f(int location, float v0, float v1) {
        if (!shimActive) return;
        GLES30.glUniform2f(location, v0, v1);
    }

    public static void glUniform3f(int location, float v0, float v1, float v2) {
        if (!shimActive) return;
        GLES30.glUniform3f(location, v0, v1, v2);
    }

    public static void glUniform4f(int location, float v0, float v1, float v2, float v3) {
        if (!shimActive) return;
        GLES30.glUniform4f(location, v0, v1, v2, v3);
    }

    public static void glUniformMatrix4fv(int location, boolean transpose, float[] value, int offset) {
        if (!shimActive) return;
        GLES30.glUniformMatrix4fv(location, 1, transpose, value, offset);
    }

    public static void glEnableVertexAttribArray(int index) {
        if (!shimActive) return;
        GLES30.glEnableVertexAttribArray(index);
    }

    public static void glDisableVertexAttribArray(int index) {
        if (!shimActive) return;
        GLES30.glDisableVertexAttribArray(index);
    }

    public static void glVertexAttribPointer(int index, int size, int type, boolean normalized, int stride, long pointer) {
        if (!shimActive) return;
        GLES30.glVertexAttribPointer(index, size, type, normalized, stride, pointer);
    }

    public static void glVertexAttribPointer(int index, int size, int type, boolean normalized, int stride, java.nio.Buffer pointer) {
        if (!shimActive) return;
        GLES30.glVertexAttribPointer(index, size, type, normalized, stride, pointer);
    }

    public static void glBindAttribLocation(int program, int index, String name) {
        if (!shimActive) return;
        GLES30.glBindAttribLocation(program, index, name);
    }

    public static void glGetShaderiv(int shader, int pname, int[] params, int offset) {
        if (!shimActive) return;
        GLES30.glGetShaderiv(shader, pname, params, offset);
    }

    public static void glGetShaderiv(int shader, int pname, int[] params) {
        if (!shimActive) return;
        GLES30.glGetShaderiv(shader, pname, params);
    }

    public static String glGetShaderInfoLog(int shader) {
        if (!shimActive) return "";
        return GLES30.glGetShaderInfoLog(shader);
    }

    public static void glGetProgramiv(int program, int pname, int[] params, int offset) {
        if (!shimActive) return;
        GLES30.glGetProgramiv(program, pname, params, offset);
    }

    public static void glGetProgramiv(int program, int pname, int[] params) {
        if (!shimActive) return;
        GLES30.glGetProgramiv(program, pname, params);
    }

    public static String glGetProgramInfoLog(int program) {
        if (!shimActive) return "";
        return GLES30.glGetProgramInfoLog(program);
    }

    // ===== GL30 / VAO =====

    public static void glGenVertexArrays(int n, int[] arrays, int offset) {
        if (!shimActive) return;
        GLES30.glGenVertexArrays(n, arrays, offset);
    }

    public static void glBindVertexArray(int array) {
        if (!shimActive) return;
        GLES30.glBindVertexArray(array);
    }

    public static void glDeleteVertexArrays(int n, int[] arrays, int offset) {
        if (!shimActive) return;
        GLES30.glDeleteVertexArrays(n, arrays, offset);
    }

    // ===== Draw calls =====

    public static void glDrawArrays(int mode, int first, int count) {
        if (!shimActive) return;
        GLES30.glDrawArrays(mapDrawMode(mode), first, count);
    }

    public static void glDrawElements(int mode, int count, int type, long indices) {
        if (!shimActive) return;
        GLES30.glDrawElements(mapDrawMode(mode), count, mapDrawType(type), indices);
    }

    public static void glDrawElementsInstanced(int mode, int count, int type, long indices, int instanceCount) {
        if (!shimActive) return;
        GLES31.glDrawElementsInstanced(mapDrawMode(mode), count, mapDrawType(type), indices, instanceCount);
    }

    // ===== Texture =====

    public static void glGenTextures(int n, int[] textures, int offset) {
        if (!shimActive) return;
        GLES30.glGenTextures(n, textures, offset);
    }

    public static void glBindTexture(int target, int texture) {
        if (!shimActive) return;
        GLES30.glBindTexture(target, texture);
    }

    public static void glTexImage2D(int target, int level, int internalformat, int width, int height, int border, int format, int type, java.nio.Buffer pixels) {
        if (!shimActive) return;
        GLES30.glTexImage2D(target, level, internalformat, width, height, border, format, type, pixels);
    }

    public static void glTexSubImage2D(int target, int level, int xoffset, int yoffset, int width, int height, int format, int type, java.nio.Buffer pixels) {
        if (!shimActive) return;
        GLES30.glTexSubImage2D(target, level, xoffset, yoffset, width, height, format, type, pixels);
    }

    public static void glTexParameteri(int target, int pname, int param) {
        if (!shimActive) return;
        GLES30.glTexParameteri(target, pname, param);
    }

    public static void glTexParameterf(int target, int pname, float param) {
        if (!shimActive) return;
        GLES30.glTexParameterf(target, pname, param);
    }

    public static void glDeleteTextures(int n, int[] textures, int offset) {
        if (!shimActive) return;
        GLES30.glDeleteTextures(n, textures, offset);
    }

    public static void glActiveTexture(int texture) {
        if (!shimActive) return;
        GLES30.glActiveTexture(texture);
    }

    public static void glGenerateMipmap(int target) {
        if (!shimActive) return;
        GLES30.glGenerateMipmap(target);
    }

    // ===== State queries =====

    public static String glGetString(int name) {
        if (!shimActive) return null;
        return GLES30.glGetString(name);
    }

    public static void glGetIntegerv(int pname, int[] data, int offset) {
        if (!shimActive) return;
        GLES30.glGetIntegerv(pname, data, offset);
    }

    public static void glGetFloatv(int pname, float[] data, int offset) {
        if (!shimActive) return;
        GLES30.glGetFloatv(pname, data, offset);
    }

    public static int glGetError() {
        if (!shimActive) return 0;
        return GLES30.glGetError();
    }

    // ===== Mapping functions =====

    private static int mapCap(int cap) {
        return switch (cap) {
            case 0x0B44 -> GLES30.GL_CULL_FACE;
            case 0x0B71 -> GLES30.GL_DEPTH_TEST;
            case 0x0BE2 -> GLES30.GL_BLEND;
            case 0x0B90 -> GLES30.GL_STENCIL_TEST;
            case 0x0C11 -> GLES30.GL_SCISSOR_TEST;
            case 0x0B46 -> GLES30.GL_POLYGON_OFFSET_FILL;
            case 0x0D50 -> GLES30.GL_SAMPLE_ALPHA_TO_COVERAGE;
            case 0x809E -> GLES30.GL_SAMPLE_COVERAGE;
            case 0x0D05 -> GLES30.GL_DITHER;
            default -> -1;
        };
    }

    private static int mapBlendFactor(int factor) {
        return switch (factor) {
            case 0 -> GLES30.GL_ZERO;
            case 1 -> GLES30.GL_ONE;
            case 0x0300 -> GLES30.GL_SRC_COLOR;
            case 0x0301 -> GLES30.GL_ONE_MINUS_SRC_COLOR;
            case 0x0302 -> GLES30.GL_SRC_ALPHA;
            case 0x0303 -> GLES30.GL_ONE_MINUS_SRC_ALPHA;
            case 0x0304 -> GLES30.GL_DST_ALPHA;
            case 0x0305 -> GLES30.GL_ONE_MINUS_DST_ALPHA;
            case 0x0306 -> GLES30.GL_DST_COLOR;
            case 0x0307 -> GLES30.GL_ONE_MINUS_DST_COLOR;
            case 0x0308 -> GLES30.GL_SRC_ALPHA_SATURATE;
            default -> factor;
        };
    }

    private static int mapDepthFunc(int func) {
        return switch (func) {
            case 0x0200 -> GLES30.GL_NEVER;
            case 0x0201 -> GLES30.GL_LESS;
            case 0x0202 -> GLES30.GL_EQUAL;
            case 0x0203 -> GLES30.GL_LEQUAL;
            case 0x0204 -> GLES30.GL_GREATER;
            case 0x0205 -> GLES30.GL_NOTEQUAL;
            case 0x0206 -> GLES30.GL_GEQUAL;
            case 0x0207 -> GLES30.GL_ALWAYS;
            default -> GLES30.GL_LESS;
        };
    }

    private static int mapCullFace(int mode) {
        return switch (mode) {
            case 0x0404 -> GLES30.GL_FRONT;
            case 0x0405 -> GLES30.GL_BACK;
            case 0x0408 -> GLES30.GL_FRONT_AND_BACK;
            default -> GLES30.GL_BACK;
        };
    }

    private static int mapDrawMode(int mode) {
        return switch (mode) {
            case 0x0000 -> GLES30.GL_POINTS;
            case 0x0001 -> GLES30.GL_LINES;
            case 0x0003 -> GLES30.GL_LINE_STRIP;
            case 0x0002 -> GLES30.GL_LINE_LOOP;
            case 0x0004 -> GLES30.GL_TRIANGLES;
            case 0x0005 -> GLES30.GL_TRIANGLE_STRIP;
            case 0x0006 -> GLES30.GL_TRIANGLE_FAN;
            default -> mode;
        };
    }

    private static int mapDrawType(int type) {
        return switch (type) {
            case 0x1400 -> GLES30.GL_UNSIGNED_BYTE;
            case 0x1401 -> GLES30.GL_UNSIGNED_SHORT;
            case 0x1405 -> GLES30.GL_UNSIGNED_INT;
            default -> type;
        };
    }

    private static int mapClearMask(int mask) {
        int result = 0;
        if ((mask & 0x00004000) != 0) result |= GLES30.GL_COLOR_BUFFER_BIT;   // GL_COLOR_BUFFER_BIT
        if ((mask & 0x00000100) != 0) result |= GLES30.GL_DEPTH_BUFFER_BIT;   // GL_DEPTH_BUFFER_BIT
        if ((mask & 0x00000400) != 0) result |= GLES30.GL_STENCIL_BUFFER_BIT; // GL_STENCIL_BUFFER_BIT
        return result;
    }

    private static int mapShaderType(int type) {
        return switch (type) {
            case 0x8B31 -> GLES30.GL_VERTEX_SHADER;
            case 0x8B30 -> GLES30.GL_FRAGMENT_SHADER;
            case 0x8DD9 -> GLES31.GL_GEOMETRY_SHADER;
            case 0x8E87 -> GLES31.GL_TESS_CONTROL_SHADER;
            case 0x8E88 -> GLES31.GL_TESS_EVALUATION_SHADER;
            case 0x91B9 -> GLES31.GL_COMPUTE_SHADER;
            default -> type;
        };
    }

    private static String convertGLSLtoESSL(String source) {
        String result = source;

        // Version directive
        if (!result.contains("#version")) {
            result = "#version 300 es\n" + result;
        } else {
            result = result.replaceAll("#version\\s+\\d+", "#version 300 es");
        }

        // Precision
        if (!result.contains("precision highp float")) {
            result = result.replaceFirst("#version 300 es", "#version 300 es\nprecision highp float;\nprecision highp int;");
        }

        // Replace deprecated
        result = result
            .replace("gl_FragColor", "fragColor")
            .replace("gl_FragData", "fragData")
            .replace("texture2D(", "texture(")
            .replace("textureCube(", "texture(")
            .replace("texture2DProj(", "textureProj(")
            .replace("textureCubeLod(", "textureLod(")
            .replace("attribute ", "in ")
            .replace("varying ", "out ");

        return result;
    }
